    'architecture-diagram-mermaid': 'آموزش نمودار معماری',
    'packet-diagram-mermaid': 'آموزش Packet Diagram در Mermaid',
    'sankey-diagram-mermaid': 'آموزش نمودار Sankey در Mermaid',
    'ishikawa-diagram-mermaid': 'آموزش نمودار استخوان ماهی در Mermaid',
    'quadrant-chart-mermaid': 'آموزش Quadrant Chart در Mermaid',
    'swimlane-diagram-mermaid': 'آموزش Swimlane Diagram در Mermaid',
    'radar-chart-mermaid': 'آموزش Radar Chart در Mermaid',
    'pie-chart-mermaid': 'آموزش Pie Chart در Mermaid',
    'xy-chart-mermaid': 'آموزش XY Chart',
    'user-journey-mermaid': 'آموزش نقشه سفر کاربر',
    'requirement-diagram-mermaid': 'آموزش Requirement Diagram در Mermaid',
    'timeline-mermaid': 'آموزش Timeline در Mermaid',
    'kanban-mermaid': 'آموزش Kanban در Mermaid',
    'gitgraph-mermaid': 'آموزش GitGraph در Mermaid',
